from taf.ue.tm500.asc.command.versions import v0_0_0
# import classes in v0_0_0 is required to make them visible when import v1_16_0


class ShowGroups(v0_0_0.ShowGroups):
    def _parse_output(self, content):
        lines = self._split_lines(content)
        groups = []
        for line in lines:
            if not line.endswith(":"):
                continue
            attributes = self._split_columns(line)
            if len(attributes) <= 1:
                continue
            groups.append(tuple(attributes))
        return groups
